-- Manchester demo data seed (generated by build.sh; edit the files in parts/, not this one).
-- Safe to run again: it first removes what an earlier run added.
begin;
-- Removes everything an earlier run of the Manchester demo seed added (rows whose id starts with dd000000-).
-- It does NOT undo: moving Testing Student into the demo class and setting them to Grade 9, or the Testing Teacher's class link.
create or replace function pg_temp.is_demo(u uuid) returns boolean language sql immutable as $$ select u::text like 'dd000000-%' $$;

-- cover for the demo absence first (only if migration 073 is applied): it points at demo lesson plans and lessons, which are removed below
do $$ begin
  if to_regclass('public.substitution_assignments') is not null then
    delete from substitution_assignments where pg_temp.is_demo(id);
    delete from teacher_absences where pg_temp.is_demo(id);
  end if;
end $$;

delete from marking_point_responses where response_id in (select r.id from responses r join exam_sessions s on s.id = r.session_id where pg_temp.is_demo(s.id));
delete from responses where session_id in (select id from exam_sessions where pg_temp.is_demo(id));
delete from exam_sessions where pg_temp.is_demo(id);
delete from final_exam_questions where pg_temp.is_demo(final_exam_id);
delete from final_exam_class_groups where pg_temp.is_demo(final_exam_id);
update draft_exams set published_final_exam_id = null where pg_temp.is_demo(id);
delete from final_exams where pg_temp.is_demo(id);
delete from questions where pg_temp.is_demo(draft_exam_id);
delete from draft_exam_class_groups where pg_temp.is_demo(draft_exam_id);
delete from draft_exams where pg_temp.is_demo(id);

-- learning part
delete from department_resources where pg_temp.is_demo(id);
delete from lesson_plans where pg_temp.is_demo(id);
delete from flashcards where pg_temp.is_demo(deck_id);
delete from flashcard_decks where pg_temp.is_demo(id);
delete from learning_check_attempts where pg_temp.is_demo(lesson_id);
delete from learning_progress where pg_temp.is_demo(lesson_id);
delete from learning_check_questions where pg_temp.is_demo(lesson_id);
delete from learning_assignments where pg_temp.is_demo(lesson_id);
delete from learning_lessons where pg_temp.is_demo(id);

-- demo topics (only if nothing real uses them), and the morning-register rows the seed marked for the demo class
delete from curriculum_topics ct where pg_temp.is_demo(ct.id)
  and not exists (select 1 from questions q where q.topic_id = ct.id)
  and not exists (select 1 from learning_lessons l where l.topic_id = ct.id)
  and not exists (select 1 from lesson_plans p where p.topic_id = ct.id)
  and not exists (select 1 from department_resources r where r.topic_id = ct.id);
delete from daily_attendance da
where da.marked_by = (select id from profiles where full_name = 'Testing Teacher' and role = 'teacher' limit 1)
  and da.att_date >= current_date - 30
  and da.student_id in (select e.student_id from enrollments e where e.class_group_id in
        (select tcg.class_group_id from teacher_class_groups tcg where tcg.teacher_id = (select id from profiles where full_name = 'Testing Teacher' and role = 'teacher' limit 1)));

-- the demo timetable
-- the second pack's attendance (the English and Science teachers' classes)
delete from daily_attendance da
where da.att_date >= current_date - 30
  and da.marked_by in (select id from profiles where full_name in ('Testing English Teacher', 'Testing Science Teacher') and role = 'teacher')
  and da.student_id in (select e.student_id from enrollments e where e.class_group_id in
        (select tcg.class_group_id from teacher_class_groups tcg where tcg.teacher_id in (select id from profiles where full_name in ('Testing English Teacher', 'Testing Science Teacher') and role = 'teacher')));

-- school part: the demo timetable
delete from section_enrollments where pg_temp.is_demo(section_id);
delete from timetable_sections where pg_temp.is_demo(id);

-- weekly class feedback (only if migration 091 is applied)
do $$ begin
  if to_regclass('public.weekly_class_feedback') is not null then
    delete from weekly_class_feedback where pg_temp.is_demo(id);
    delete from weekly_class_reflections where pg_temp.is_demo(id);
  end if;
end $$;

-- student support plans (only if migration 092 is applied)
do $$ begin
  if to_regclass('public.support_cases') is not null then
    delete from support_actions where pg_temp.is_demo(id);
    delete from support_cases where pg_temp.is_demo(id);
  end if;
end $$;

-- the demo report-card term (its comments and attendance go with it)
delete from academic_terms where pg_temp.is_demo(id);
-- ====================== ASSESS: topics, tests, questions, results ======================
create or replace function pg_temp.did(n int) returns uuid language sql immutable as $$ select ('dd000000-0000-4000-8000-' || lpad(n::text, 12, '0'))::uuid $$;
create or replace function pg_temp.rnd(k text) returns numeric language sql immutable as $$ select (abs(hashtextextended(k, 7)) % 10000) / 10000.0 $$;
-- the last weekday on or before (today minus n days), so no test is dated on a weekend
create or replace function pg_temp.wk(n int) returns date language sql stable as $$
  select case extract(dow from (current_date - n)) when 0 then current_date - n - 2 when 6 then current_date - n - 1 else current_date - n end $$;

create temp table demo_ctx (teacher uuid, hod uuid, principal uuid, student uuid, dept uuid, class_id uuid, class_name text);

do $$
declare
  v_teacher uuid; v_hod uuid; v_principal uuid; v_student uuid; v_dept uuid; v_class uuid; v_class_name text; v_n int;
begin
  select id, department_id into v_teacher, v_dept from profiles where full_name = 'Testing Teacher' and role = 'teacher' limit 1;
  select id into v_hod from profiles where full_name = 'Testing HOD' and role = 'supervisor' limit 1;
  select id into v_principal from profiles where full_name = 'Testing Principal' and role = 'principal' limit 1;
  select id into v_student from profiles where student_id = '54321' and role = 'student' limit 1;
  if v_teacher is null then raise exception 'Cannot find the account named Testing Teacher (role teacher)'; end if;
  if v_hod is null then raise exception 'Cannot find the account named Testing HOD (role supervisor)'; end if;
  if v_principal is null then raise exception 'Cannot find the account named Testing Principal (role principal)'; end if;
  if v_student is null then raise exception 'Cannot find the student with ID 54321'; end if;
  if v_dept is null then raise exception 'Testing Teacher has no department'; end if;

  -- the demo class: the Grade 9 class with the most students (the test student joins it)
  select cg.id, cg.name into v_class, v_class_name
  from class_groups cg left join enrollments e on e.class_group_id = cg.id
  where cg.year_grade = 'Grade 9' and cg.department_id = v_dept
  group by cg.id, cg.name order by count(e.id) desc, cg.name limit 1;
  if v_class is null then raise exception 'There is no Grade 9 class in the teacher''s department'; end if;

  -- Testing Student: Grade 9, in the demo class only
  update profiles set grade_level = 9 where id = v_student;
  delete from enrollments where student_id = v_student and class_group_id <> v_class;
  insert into enrollments (student_id, class_group_id) values (v_student, v_class) on conflict do nothing;
  -- Testing Teacher teaches the demo class and Mathematics
  insert into teacher_class_groups (teacher_id, class_group_id) values (v_teacher, v_class) on conflict do nothing;
  insert into teacher_subjects (teacher_id, department_id, subject)
    select v_teacher, v_dept, 'Mathematics' where not exists (select 1 from teacher_subjects where teacher_id = v_teacher and subject = 'Mathematics');
  update profiles set department_id = v_dept where id = v_hod and department_id is null;
  insert into department_subjects (department_id, subject) select v_dept, 'Mathematics' where not exists (select 1 from department_subjects where department_id = v_dept and lower(btrim(subject)) = 'mathematics');

  select count(*) into v_n from enrollments where class_group_id = v_class;
  if v_n < 12 then raise exception 'The demo class % has only % students; need at least 12', v_class_name, v_n; end if;
  insert into demo_ctx values (v_teacher, v_hod, v_principal, v_student, v_dept, v_class, v_class_name);
end $$;

-- Grade 9 Mathematics topics (added only if missing)
insert into curriculum_topics (id, code, subject, grade, unit, name, status, sort_order)
select pg_temp.did(100 + t.n), '', 'Mathematics', 9, t.unit, t.name, 'active', t.n
from (values
  (1, 'Consumer arithmetic', 'Simple interest'), (2, 'Consumer arithmetic', 'Compound interest'),
  (3, 'Ratio and proportion', 'Direct and inverse variation'), (4, 'Ratio and proportion', 'Compound ratios and rates'),
  (5, 'Algebra', 'Expanding and factorising expressions'), (6, 'Algebra', 'Solving quadratic equations'), (7, 'Algebra', 'Simultaneous linear equations'),
  (8, 'Geometry', 'Pythagoras'' theorem'), (9, 'Coordinate geometry and graphs', 'Equation of a straight line')
) as t(n, unit, name)
where not exists (select 1 from curriculum_topics c where lower(btrim(c.subject)) = 'mathematics' and c.grade = 9 and lower(btrim(c.name)) = lower(btrim(t.name)) and c.status <> 'archived');

